def find_largest_k(N: int, S: str, T: str) -> int:
    cnt = [0] * 26
    pos = [[] for _ in range(26)]
    pre = [[0] * 26 for _ in range(len(S) + 1)]

    for i, c in enumerate(S * 2):
        idx = ord(c) - ord('a')
        pos[idx].append(i)

    for i in range(26):
        cnt[i] = len(pos[i]) // 2

    for i in range(1, len(S) + 1):
        pre[i] = pre[i - 1][:]
        pre[i][ord(S[i - 1]) - ord('a')] += 1

    def check(m):
        it = 0
        for i in range(len(T)):
            d = ord(T[i]) - ord('a')
            if cnt[d] == 0:
                return False
            r = (m - 1) % cnt[d] + 1
            b = (m - r) // cnt[d]
            it += len(S) * b
            nx = pos[d][pre[it % len(S)][d] + r - 1]
            it += nx + 1 - it % len(S)
            if it > len(S) * N:
                return False
        return True

    ans = 0
    l, r = 0, len(S) * N // len(T)
    while l <= r:
        mid = (l + r) >> 1
        if check(mid):
            ans = mid
            l = mid + 1
        else:
            r = mid - 1
    return ans
